// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 am) public {
        // bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        initialBalance = bound(initialBalance, minSum, 1e18);
        am = bound(am, 0, initialBalance);

        // setup contract
        c.SetMinSum(minSum);
        c.Initialized();

        // fund caller
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSelector(c.Collect.selector, am));

        if (balanceBefore >= minSum && balanceBefore >= am) {
            // Collect should succeed
            assertTrue(success, "Collect should succeed");
            // balance should decrease by am (the invariant)
            assertTrue(c.balances(caller) == balanceBefore - am, "Balance must decrease by _am");
        } else {
            // Collect should revert
            assertTrue(!success, "Collect should revert");
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        // Bound inputs to reasonable ranges
        minSum = bound(minSum, 0, 1e18);
        depositAmount = bound(depositAmount, 0, 1e18);
        collectAmount = bound(collectAmount, 0, depositAmount); // ensure sufficient balance

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xcafe));
        c.Initialized();

        // Fund caller and deposit
        vm.deal(caller, depositAmount + 1e18);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balances before collect
        uint256 callerBalanceBefore = c.balances(caller);
        uint256 contractBalanceBefore = address(c).balance;

        // Attempt collect (may revert if caller balance < minSum or < collectAmount)
        bool reverted = false;
        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));
        if (!success) reverted = true;

        // Assert that if successful and condition holds, total supply is unchanged
        bool conditionHolds = (callerBalanceBefore >= minSum && callerBalanceBefore >= collectAmount);
        if (!reverted && conditionHolds) {
            uint256 callerBalanceAfter = c.balances(caller);
            uint256 contractBalanceAfter = address(c).balance;
            // Total supply = sum of all balances + contract balance
            // Since we only change caller's balance, we check that:
            // callerBalanceBefore + contractBalanceBefore == callerBalanceAfter + contractBalanceAfter
            assertTrue(callerBalanceBefore + contractBalanceBefore == callerBalanceAfter + contractBalanceAfter, "Total supply invariant violated");
        }
    }
}

