pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 initialBalance, uint256 amt) public {
        // Ensure minSum fits in uint256 range
        minSum = bound(minSum, 0, type(uint256).max);
        // Ensure initialBalance fits in uint256 range and is at least minSum
        initialBalance = bound(initialBalance, 0, type(uint256).max);
        // Ensure amt is <= initialBalance for valid Collect precondition
        amt = bound(amt, 0, initialBalance);
        // Avoid zero address to ensure successful deposit
        vm.assume(caller != address(0));
        // Setup: Simulate the contract initialization
        c.SetMinSum(minSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();
        // Fund the contract and the caller's balance via Deposit
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.Deposit{value: initialBalance}();
        // Now attempt Collect
        uint256 balanceBefore = c.balances(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amt));
        uint256 balanceAfter = c.balances(caller);
        // The rule: if the call succeeded and caller had sufficient balance, balance decreased by amt
        assertTrue(!success || (balanceBefore >= minSum && balanceBefore >= amt && balanceAfter == balanceBefore - amt));
    }
}

contract LogFile {
    struct Message {
        address Sender;
        string  Data;
        uint Val;
        uint  Time;
    }

    Message[] public History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val,string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

