pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 initialBalance, uint256 minSum, uint256 am) public {
        // Bound inputs to reasonable ranges
        am = bound(am, 0, 1e18);
        initialBalance = bound(initialBalance, 0, 1e18);
        minSum = bound(minSum, 0, 1e18);

        // Ensure caller has enough initial balance
        vm.assume(initialBalance >= am);
        vm.assume(initialBalance >= minSum);

        // Fund the caller and initialize contract
        vm.deal(caller, initialBalance + 1 ether); // extra for gas
        vm.deal(address(c), 0);

        // Set MinSum and initialize
        c.SetMinSum(minSum);
        c.Initialized();

        // Deposit initialBalance into contract
        vm.prank(caller);
        c.Deposit{value: initialBalance}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", am));

        // Only if Collect succeeded
        if (success) {
            uint256 balanceAfter = c.balances(caller);
            // General rule: balance must not increase after Collect
            assertTrue(balanceAfter <= balanceBefore, "balance increased after Collect");
        }
    }
