pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 minSum, uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(caller != address(0));
        vm.assume(collectAmount > 0);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit some funds so the caller has balance
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record total Ether before Collect
        uint256 totalBefore = address(c).balance;
        // We cannot read the balances mapping directly, but we can observe the contract balance only.
        // However, the invariant "total supply unchanged" holds for the reference: the contract balance decreases by _am, and the caller receives _am.
        // For the mutant, the contract balance decreases by _am (the same), but the caller's balance in the mapping increases, so the mapping total (not observable directly) increases.
        // So we cannot observe the invariant via public getters. We need a different rule.
        // Alternative rule: The contract balance after Collect should be exactly totalBefore - collectAmount if the Collect succeeds.

        vm.prank(caller);
        (bool success,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        if (success) {
            uint256 totalAfter = address(c).balance;
            // In the reference, the contract sends _am to caller, so balance decreases by _am exactly.
            // In the mutant, the same send happens, so contract balance also decreases by _am.
            // The difference is in the mapping, which we cannot read. So this rule also holds for mutant!
            // Need another approach.
            // Actually, the mutant changes the mapping addition, but the ether flow is the same. So contract balance behavior is identical.
            // We need a rule that distinguishes the mapping change. Since mapping is not public, we cannot observe its value directly.
            // The only way to observe mapping is through a getter. But the mapping is public, so we can call c.balances(caller)! Yes, balances is public!
        }
    }
}

