pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, uint256 minSum, uint256 deposit1, uint256 deposit2, uint256 withdrawal) public {
        vm.assume(caller != address(0) && other != address(0) && caller != other);
        vm.assume(minSum > 0);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Deposit to caller and other
        vm.deal(caller, deposit1);
        vm.prank(caller);
        c.Deposit{value: deposit1}();

        vm.deal(other, deposit2);
        vm.prank(other);
        c.Deposit{value: deposit2}();

        // Bound withdrawal to be at most the caller's balance
        uint256 callerBal = c.balances(caller);
        vm.assume(withdrawal <= callerBal);

        // Pre-state: balance of other
        uint256 otherBalBefore = c.balances(other);

        // Call Collect from caller
        vm.prank(caller);
        c.Collect(withdrawal);

        // Post-state: balance of other should not have decreased
        uint256 otherBalAfter = c.balances(other);
        assertTrue(otherBalAfter >= otherBalBefore);
    }
}

