pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 depositAmount, uint256 minSum, uint256 collectAmount) public {
        // Bound inputs to reasonable ranges
        depositAmount = bound(depositAmount, 0, 1e18);
        minSum = bound(minSum, 1, 1000);
        collectAmount = bound(collectAmount, 0, 1e18);
        vm.assume(minSum > 0);

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));
        c.Initialized();

        // Fund caller
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.Deposit{value: depositAmount}();

        // Record balance before Collect
        uint256 balanceBefore = c.balances(caller);

        // Call Collect
        vm.prank(caller);
        c.Collect(collectAmount);

        // Record balance after Collect
        uint256 balanceAfter = c.balances(caller);

        // General rule: if balance decreased, then balanceBefore >= minSum and decrease == collectAmount
        if (balanceAfter < balanceBefore) {
            assertTrue(balanceBefore >= minSum, "Balance decreased but was below MinSum");
            assertTrue(balanceBefore - balanceAfter == collectAmount, "Decrease amount mismatch");
        } else {
            // If balance did not decrease, it must be unchanged (since no other effect)
            assertTrue(balanceAfter == balanceBefore, "Balance changed without collection");
        }
    }
}

