pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address alice, address bob, address charlie, uint256 amt1, uint256 amt2, uint256 collectAmt) public {
        // Bound amounts to avoid overflow
        amt1 = bound(amt1, 1, 1e18);
        amt2 = bound(amt2, 1, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Make deposits from two different users
        vm.deal(alice, amt1);
        vm.prank(alice);
        c.Deposit{value: amt1}();

        vm.deal(bob, amt2);
        vm.prank(bob);
        c.Deposit{value: amt2}();

        // Record total balances before Collect
        uint256 balBefore = c.balances(alice) + c.balances(bob) + c.balances(charlie);

        // Call Collect from alice
        vm.prank(alice);
        (bool ok,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmt));

        // Record total balances after Collect (whether it reverted or not)
        uint256 balAfter = c.balances(alice) + c.balances(bob) + c.balances(charlie);

        // General rule: total balances never exceed pre-deposit total (which was sum of deposits)
        // and never go negative (due to subtraction bug)
        uint256 totalDeposited = amt1 + amt2;
        assertTrue(balAfter <= totalDeposited && balAfter >= 0);
    }
}

