pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, address third, uint256 deposit1, uint256 deposit2, uint256 collectAmount) public {
        // Initialize the contract
        c.SetMinSum(0);  // So Collect is always allowed based on MinSum
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Ensure amounts are reasonable
        vm.assume(deposit1 <= 1e30 && deposit2 <= 1e30 && collectAmount <= 1e30);

        // Fund caller and other
        vm.deal(caller, deposit1 + deposit2 + collectAmount);
        vm.deal(other, deposit1 + deposit2 + collectAmount);
        vm.deal(third, deposit1 + deposit2 + collectAmount);

        // Record caller's initial balance
        uint256 initialBalance = c.balances(caller);

        // Make deposits from various addresses
        vm.prank(caller);
        c.Deposit{value: deposit1}();

        vm.prank(other);
        c.Deposit{value: deposit2}();

        vm.prank(third);
        c.Deposit{value: deposit2}();

        // Now call Collect as caller
        vm.prank(caller);
        // Bound collectAmount to prevent overflow but may still be > balance
        vm.assume(collectAmount <= c.balances(caller));
        c.Collect(collectAmount);

        // The rule: After Collect, caller's balance should be <= initialBalance + sum of deposits made by caller (but deposits already added, so balance should be >= initialBalance after deposits, and Collect can only reduce it)
        // Simpler: balance after Collect should be <= initialBalance + deposit1 (since caller only deposited once)
        uint256 maxAllowed = initialBalance + deposit1;
        assertTrue(c.balances(caller) <= maxAllowed, "Caller balance exceeded maximum possible after Collect");
    }
}

