pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address other, address logAddr, uint minSum, uint depositAmt, uint collectAmt) public {
        // Bound inputs to reasonable ranges
        depositAmt = bound(depositAmt, 0, 1e18);
        collectAmt = bound(collectAmt, 0, 1e18);
        minSum = bound(minSum, 0, 1e18);

        // Ensure caller and other are distinct (avoid extra complexity)
        vm.assume(caller != address(0) && caller != other && other != address(0));
        vm.assume(logAddr != address(0));

        // Initialize the contract
        c.SetMinSum(minSum);
        c.SetLogFile(logAddr);
        c.Initialized();

        // Record balance before deposit
        uint256 balBeforeDeposit = c.balances(caller);

        // Deposit from caller
        vm.deal(caller, depositAmt);
        vm.prank(caller);
        c.Deposit{value: depositAmt}();

        // Record balance after deposit
        uint256 balAfterDeposit = c.balances(caller);
        uint256 expectedBalAfterDeposit = balBeforeDeposit + depositAmt;
        assertTrue(balAfterDeposit == expectedBalAfterDeposit, "Deposit should increase balance in reference");

        // Now try Collect with some amount
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // If Collect succeeded, then in the reference the caller's balance should have decreased by collectAmt
        if (success) {
            uint256 finalBal = c.balances(caller);
            // In reference: finalBal == balAfterDeposit - collectAmt
            // In buggy: finalBal == balAfterDeposit + collectAmt (since Deposit reduces, so balance after deposit is lower)
            // The invariant: finalBal should not be greater than expected if Collect worked
            // Actually, the reference ensures finalBal == balAfterDeposit - collectAmt if conditions held
            // So we assert that finalBal <= balAfterDeposit (cannot increase due to Collect)
            assertTrue(finalBal <= balAfterDeposit, "Balance should not increase after Collect");
        }
    }
}

