pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address alice, address bob, address charlie, uint256 depA, uint256 depB, uint256 depC, uint256 colA, uint256 colB) public {
        // Bound deposits to avoid overflow and ensure reasonable values
        depA = bound(depA, 0, 1e18);
        depB = bound(depB, 0, 1e18);
        depC = bound(depC, 0, 1e18);

        // Bound collect amounts
        colA = bound(colA, 0, 1e18);
        colB = bound(colB, 0, 1e18);

        // Initialize the contract
        c.SetMinSum(0);
        c.SetLogFile(address(0xdead));
        c.Initialized();

        // Fund accounts and make deposits
        vm.deal(alice, depA);
        vm.deal(bob, depB);
        vm.deal(charlie, depC);

        vm.prank(alice);
        c.Deposit{value: depA}();

        vm.prank(bob);
        c.Deposit{value: depB}();

        vm.prank(charlie);
        c.Deposit{value: depC}();

        // Track total balance in contract before collect
        uint256 balanceBefore = address(c).balance;

        // Perform a collect call from alice
        vm.prank(alice);
        (bool successA, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", colA));

        // Perform a collect call from bob
        vm.prank(bob);
        (bool successB, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", colB));

        // Compute expected total deposits (original sum)
        uint256 totalDeposits = depA + depB + depC;

        // Compute actual withdrawals
        uint256 withdrawnA = successA ? colA : 0;
        uint256 withdrawnB = successB ? colB : 0;
        uint256 totalWithdrawn = withdrawnA + withdrawnB;

        // Balance after collects
        uint256 balanceAfter = address(c).balance;

        // For the reference (correct) contract: totalDeposits == balanceAfter + totalWithdrawn
        // For the buggy version (deposits subtract): totalDeposits != balanceAfter + totalWithdrawn
        assertTrue(totalDeposits == balanceAfter + totalWithdrawn);
    }
}

