        // Actually, we need sum of all balances; but we only know caller's balance. 
        // For simplicity, we track total Ether deposited = contract balance + sum of all balances
        // Since nobody else has deposited, totalBefore = c.balances(caller) + address(c).balance
        uint256 ethInContract = address(c).balance;
        uint256 callerBalance = c.balances(caller);
