contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint256 depositAmount, uint256 collectAmount) public {
        // Bound deposit and collect amounts to avoid overflow/underflow
        vm.assume(depositAmount > 0 && depositAmount <= 1e30);
        vm.assume(collectAmount > 0 && collectAmount <= 1e30);
        // Ensure contract has enough balance for potential collect
        vm.assume(depositAmount >= collectAmount);
        // Set MinSum to 0 so collect is accessible
